#!/usr/bin/env python3
"""Full engagement audit: recomputes figures from source records, validates
claim_analysis.json against the CONTRACT schema, cross-checks every
library citation in every deliverable, and probes cited statutory
subsections against actual library file contents (incl. enumerated forms)."""
import csv, json, re, sys, datetime as dt
from pathlib import Path

WS = Path("/work/workspace")
DELIV = WS / "deliverable"
LIB = WS / "library"
FAILS = []
OKS = []

def ok(msg): OKS.append(msg)
def fail(msg): FAILS.append(msg)

PET = dt.date(2026, 3, 10)
W20 = PET - dt.timedelta(days=20)      # 2026-02-18
W90 = PET - dt.timedelta(days=90)      # 2025-12-10

# ---------- 1. Recompute from source records ----------
def paid_amt(paid, amount):
    p = paid.strip()
    if p.startswith("yes"): return amount
    if p.startswith("partial"):
        m = re.search(r"([\d,]+)", p)
        return int(m.group(1).replace(",", ""))
    return 0

GOODS = re.compile(r"steel", re.I)      # freight & handling / cutting services are NOT goods
invoices = {}
with open(WS / "documents" / "invoices_and_deliveries.csv") as f:
    for r in csv.DictReader(f):
        amt = int(r["amount"])
        inv = dict(amount=amt, paid=paid_amt(r["paid"], amt),
                   dd=dt.date.fromisoformat(r["delivery_date"]), desc=r["description"])
        inv["out"] = amt - inv["paid"]
        invoices[r["invoice"]] = inv

total_claim = sum(i["out"] for i in invoices.values())
b9 = {k: v for k, v in invoices.items() if v["out"] and GOODS.search(v["desc"]) and v["dd"] >= W20}
b9_amt = sum(v["out"] for v in b9.values())
guc_amt = total_claim - b9_amt

new_value = sum(v["out"] for v in invoices.values()
                if v["out"] and v["dd"] >= dt.date(2026, 2, 20))  # deliveries after both exposed payments

xfers = 0; payments = []
with open(WS / "documents" / "payment_history_12m.csv") as f:
    for r in csv.DictReader(f):
        d = dt.date.fromisoformat(r["payment_date"])
        if W90 <= d <= PET:
            xfers += int(r["amount"]); payments.append((r["payment_date"], r["amount"]))

exp = {"total": 125000, "b9": 78100, "guc": 46900, "xfers": 180000, "nv": 99400,
       "b9_inv": {"MS-7788", "MS-7815"}}
checks = [
    ("total claim from CSV", total_claim, exp["total"]),
    ("503(b)(9) from CSV", b9_amt, exp["b9"]),
    ("GUC from CSV", guc_amt, exp["guc"]),
    ("90-day transfers from CSV", xfers, exp["xfers"]),
    ("new value from CSV", new_value, exp["nv"]),
    ("b9 invoices from CSV", set(b9), exp["b9_inv"]),
    ("split 95k+85k", 95000 + 85000, xfers),
    ("dunning reconciliation 210k-85k", (48200+62400+41300+6900+36800+14400) - (48200+36800), total_claim),
]
for name, got, want in checks:
    (ok if got == want else fail)(f"arith {name}: {got} (expected {want})")

# ---------- 2. JSON schema + consistency ----------
SCHEMA = {"total_prepetition_claim": int, "general_unsecured": int, "bar_date": str,
          "stay_violations": list, "immediate_actions": list}
try:
    j = json.loads((DELIV / "claim_analysis.json").read_text())
except Exception as e:
    fail(f"claim_analysis.json does not parse: {e}"); j = None
if j:
    for k, t in SCHEMA.items():
        if k in j and isinstance(j[k], t): ok(f"json key {k}")
        else: fail(f"json key {k} missing or wrong type")
    for k in ("admin_503b9", "reclamation", "preference"):
        if k not in j: fail(f"json key {k} missing"); continue
    sub = {"admin_503b9": ["amount", "invoices"],
           "reclamation": ["available", "why"],
           "preference": ["transfers_in_90_days", "ordinary_course_defense", "new_value_defense", "net_exposure_estimate"]}
    for k, subs in sub.items():
        for s in subs:
            if s in j.get(k, {}): ok(f"json {k}.{s}")
            else: fail(f"json {k}.{s} missing")
    ocd = j["preference"]["ordinary_course_defense"]
    if "protected" in ocd and "exposed" in ocd and "reasoning" in ocd: ok("json ordinary_course_defense subkeys")
    else: fail("json ordinary_course_defense subkeys")
    pairs = [("total_prepetition_claim", j.get("total_prepetition_claim"), exp["total"]),
             ("admin amount", j["admin_503b9"].get("amount"), exp["b9"]),
             ("general_unsecured", j.get("general_unsecured"), exp["guc"]),
             ("transfers_in_90_days", j["preference"].get("transfers_in_90_days"), exp["xfers"]),
             ("new_value_defense", j["preference"].get("new_value_defense"), exp["nv"]),
             ("protected+exposed == transfers", ocd.get("protected", 0) + ocd.get("exposed", 0),
              j["preference"].get("transfers_in_90_days")),
             ("b9+guc == total", j["admin_503b9"].get("amount", 0) + j.get("general_unsecured", 0),
              j.get("total_prepetition_claim"))]
    for name, got, want in pairs:
        (ok if got == want else fail)(f"json {name}: {got} (expected {want})")
    if set(j["admin_503b9"].get("invoices", [])) == exp["b9_inv"]: ok("json 503(b)(9) invoice list")
    else: fail(f"json 503(b)(9) invoice list: {j['admin_503b9'].get('invoices')}")
    if j.get("bar_date") == "2026-06-11": ok("json bar_date 2026-06-11")
    else: fail(f"json bar_date: {j.get('bar_date')}")
    if j["reclamation"].get("available") is True: ok("json reclamation.available present")
    else: fail("json reclamation.available")

# ---------- 3. library/ references vs INDEX and disk ----------
index = (LIB / "INDEX.md").read_text()
deliv_files = sorted(DELIV.glob("*.md")) + sorted(DELIV.glob("*.json"))
refs = {}
for p in deliv_files:
    for m in re.finditer(r"library/([A-Za-z0-9_\-]+\.[A-Za-z]+)", p.read_text()):
        refs.setdefault(m.group(1), set()).add(p.name)
for name, where in sorted(refs.items()):
    in_index = name in index
    on_disk = (LIB / name).exists()
    if in_index and on_disk: ok(f"cite library/{name} (in INDEX + on disk; used in {sorted(where)})")
    else: fail(f"cite library/{name}: INDEX={in_index} disk={on_disk} used in {sorted(where)}")

# ---------- 4. cited statutory subsections must be findable in library text ----------
all_text = "\n".join(p.read_text() for p in deliv_files)
cites = set(re.findall(r"§+\s*(\d+)\((?:[a-z]\)\()??([a-z0-9]+)\)??", all_text))
# probe explicit list of authorities relied on (label -> library file -> regex allowing enumerated text)
PROBES = [
    ("362(a)(1)", "bc_362.md", r"\(a\)[\s\S]{0,2500}?\(1\)"),
    ("362(a)(6)", "bc_362.md", r"\(a\)[\s\S]{0,4000}?\(6\)"),
    ("362(k)",    "bc_362.md", r"\(k\)"),
    ("105",       "bc_362.md", r"105"),
    ("502(d)",    "bc_502d_setoff.md", r"\(d\)"),
    ("553",       "bc_502d_setoff.md", r"553"),
    ("503(b)(9)", "bc_503b9_546c.md", r"\(b\)[\s\S]{0,2500}?\(9\)"),
    ("546(c)",    "bc_503b9_546c.md", r"\(c\)"),
    ("547(b)",    "bc_547.md", r"\(b\)"),
    ("547(c)(2)", "bc_547.md", r"\(c\)[\s\S]{0,1200}?\(2\)"),
    ("547(c)(4)", "bc_547.md", r"\(c\)[\s\S]{0,3000}?\(4\)"),
    ("547(f)",    "bc_547.md", r"\(f\)"),
    ("547(g)",    "bc_547.md", r"\(g\)"),
    ("3002(c)",   "frbp_3002_3003.md", r"\(c\)"),
    ("3003(c)",   "frbp_3002_3003.md", r"\(c\)"),
]
for label, fname, pat in PROBES:
    text = (LIB / fname).read_text()
    if re.search(pat, text): ok(f"statute probe {label} found in {fname}")
    else: fail(f"statute probe {label} NOT found in {fname}")

# every section number cited anywhere in deliverables must appear in some library file
secs = set(re.findall(r"§+\s*(\d{3})", all_text))
for s in sorted(secs):
    if any(s in (LIB / f).read_text() for f in LIB.glob("*.md")): ok(f"section §{s} present in library")
    else: fail(f"section §{s} cited in deliverables but absent from library")

# ---------- 5. Kmart citation verbatim vs INDEX ----------
km = "359 F.3d 866"
used = any(km in p.read_text() for p in deliv_files)
in_idx = km in index and "Kmart" in index
if used and in_idx: ok("Kmart cite matches INDEX entry")
else: fail(f"Kmart cite used={used} in_index={in_idx}")

# ---------- 6. required deliverables + STATUS ----------
req = ["claim_analysis.json", "proof_of_claim_draft.md", "advice_to_ceo.md", "STATUS.md"]
for r_ in req:
    if (DELIV / r_).exists(): ok(f"deliverable {r_} exists")
    else: fail(f"required deliverable {r_} MISSING")
st = (DELIV / "STATUS.md").read_text().strip()
if st.splitlines()[0].startswith(("STATUS: COMPLETE", "STATUS: BLOCKED")): ok("STATUS first line valid")
else: fail(f"STATUS first line: {st.splitlines()[0] if st else 'EMPTY'}")
for f2 in ("client_answers_round1.md", "client_answers_round2.md"):
    if (DELIV / f2).exists() and f2 in st: ok(f"{f2} exists and is referenced in STATUS.md")
    else: fail(f"{f2} exists={((DELIV/f2).exists())} referenced_in_STATUS={f2 in st}")

print("PASS" if not FAILS else "FAIL")
for m in FAILS: print("  FAIL:", m)
print(f"({len(OKS)} checks passed, {len(FAILS)} failed)")
sys.exit(1 if FAILS else 0)

